-- 121: legacy client table: oid -> id and every *_oid -> *_id; route_area_map.area_oid -> area_id (follows area_master.id). Safe to re-run.

USE acme_db;
SET @s := IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'client' AND column_name = 'oid') > 0, 'ALTER TABLE client CHANGE COLUMN oid id BIGINT NOT NULL AUTO_INCREMENT', 'SELECT 1');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;
SET @s := IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = 'client' AND column_name = 'client_type_oid') > 0, 'ALTER TABLE client CHANGE COLUMN client_type_oid client_type_id BIGINT NOT NULL', 'SELECT 1');
